"""The SSH ingress wizard exposes only public host and port data to the browser."""
import json
import wpp_ssh_cascade as ssh


def render(connections,domain,path,csrf,standalone=False):
    try:state=ssh.load('/etc/web-proxy-panel/ssh-cascades.json');servers=state['servers']
    except ssh.SSHError:state={};servers={}
    rows=[]
    for item in connections:
        if not ssh.supports_connection(item):continue
        try:entry=ssh.client_entry(item.get('config',{}).get('ssh_entry')) if item.get('config',{}).get('ssh_entry') else {}
        except ssh.SSHError:entry={}
        node=servers.get(entry.get('server_id'),{})
        route=state.get('routes',{}).get(item['id'],{});hops=ssh.Controller.hops(route) if route else []
        middle=hops[1] if len(hops)>1 else {};second=servers.get(middle.get('server_id'),{})
        rows.append({'id':item['id'],'name':item['name'],'protocol':item['protocol'],
                     'entry':entry,'ssh_port':node.get('ssh_port',22),'exit_ip':route.get('exit_ip',''),
                     'middle':{'host':second.get('host',''),'ssh_port':second.get('ssh_port',22),'listen_port':middle.get('config',{}).get('listen_port',443)}})
    data=json.dumps({'connections':rows,'domain':domain,'path':path,'csrf':csrf,'standalone':standalone},ensure_ascii=False).replace('<','\\u003c')
    return '''<style>
#sshCascadeDialog{width:min(780px,calc(100vw - 28px));max-height:92vh;padding:0;overflow:auto}#sshCascadeDialog>.dialog-head{margin:0;padding:20px 22px;border-bottom:1px solid var(--line);background:var(--surface)}#sshCascadeDialog>.dialog-head p{margin:6px 0 0;font-size:14px}#sshCascadeDialog form{padding:22px}#sshCascadeDialog .ssh-intro{padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--input);margin-bottom:18px;font-size:15px;line-height:1.65}#sshCascadeDialog .ssh-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}#sshCascadeDialog label{display:grid;gap:8px;margin:0;font-size:14px}#sshCascadeDialog input{width:100%;font-size:16px}#sshCascadeDialog .ssh-pin{display:block;overflow-wrap:anywhere;font-size:13px;color:var(--text);margin:10px 0}#sshCascadeDialog .ssh-status{font-size:15px;line-height:1.6;white-space:pre-wrap}#sshCascadeDialog .ssh-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}#sshCascadeDialog .ssh-note{font-size:14px;line-height:1.6;color:var(--muted);margin:14px 0}@media(max-width:600px){#sshCascadeDialog .ssh-grid{grid-template-columns:1fr}}
</style><dialog id="sshCascadeDialog" aria-labelledby="sshCascadeTitle"><div class="dialog-head"><div><h2 id="sshCascadeTitle">RU-вход по SSH</h2><p data-ssh-connection></p></div><button type="button" data-ssh-close aria-label="Закрыть">×</button></div><form autocomplete="off"><div class="ssh-intro"><b><span data-ssh-scheme>Клиент → RU-1 → зарубежный VPS → интернет</span></b><br>Панель остаётся на зарубежном сервере. <span data-ssh-transport></span></div><div class="ssh-grid"><label>IPv4 RU-сервера<input name="host" required placeholder="Публичный IP RU-сервера" autocomplete="off"></label><label>Порт SSH<input name="ssh_port" type="number" min="1" max="65535" value="22" required></label><label>Пользователь SSH<input value="root" readonly></label><label>Пароль root<input name="password" type="password" autocomplete="new-password" placeholder="Только для первой настройки"></label><label>Порт подключения на RU<input name="listen_port" type="number" min="1" max="65535" value="443" required></label><label>IPv4 зарубежного VPS<input name="exit_ip" placeholder="Определится автоматически" autocomplete="off"></label></div><label style="display:flex;align-items:center;gap:12px;margin-top:20px"><input type="checkbox" name="double_hop" style="width:auto"> Добавить второй RU-сервер</label><fieldset data-ssh-middle hidden style="border:1px solid var(--line);border-radius:12px;margin-top:16px;padding:18px"><legend>Второй сервер · RU-2</legend><div class="ssh-grid"><label>IPv4 RU-2<input name="middle_host" placeholder="Публичный IP второго RU-сервера"></label><label>Порт SSH RU-2<input name="middle_ssh_port" type="number" min="1" max="65535" value="22"></label><label>Пользователь SSH<input value="root" readonly></label><label>Пароль root RU-2<input name="middle_password" type="password" autocomplete="new-password" placeholder="Только для первой настройки"></label><label>Порт подключения RU-2<input name="middle_listen_port" type="number" min="1" max="65535" value="443"></label></div><button type="button" data-ssh-middle-inspect style="margin-top:16px">Проверить SSH-ключ RU-2</button><code class="ssh-pin" data-ssh-middle-pin></code></fieldset><p class="ssh-note">Настройка добавит служебный SSH-ключ с доступом только к управлению этой службой. Пароль root не сохраняется. Занятые порты и чужие службы не заменяются. <span data-ssh-firewall></span></p><div class="ssh-actions"><button type="button" data-ssh-inspect>Проверить SSH-ключ</button><button type="button" data-ssh-check>Проверить интернет</button></div><code class="ssh-pin" data-ssh-pin></code><p class="ssh-note">Перед установкой сверьте отпечаток SSH-ключа RU-сервера. Пароль отправляется только после проверки выбранного ключа.</p><p role="status" class="ssh-status" data-ssh-status></p><div class="ssh-actions"><button class="primary" type="submit" data-ssh-install disabled>Настроить RU-вход</button><button type="button" class="danger" data-ssh-remove>Отключить RU-вход</button></div><p class="ssh-note">После применения или отключения обновите подписку либо заново добавьте отдельное подключение в приложении.</p></form></dialog><script type="application/json" id="sshCascadeData">'''+data+'''</script><script>(()=>{
'use strict';
const data=JSON.parse(document.getElementById('sshCascadeData').textContent),dialog=document.getElementById('sshCascadeDialog'),form=dialog.querySelector('form'),base=document.getElementById('connectionEditor'),original=document.getElementById('connectionForm');if(!base||!original)return;
const records=new Map(data.connections.map(c=>[c.id,c])),status=form.querySelector('[data-ssh-status]'),pinText=form.querySelector('[data-ssh-pin]'),install=form.querySelector('[data-ssh-install]');
let current=null,pin='',middlePin='',busy=false,baseline='';const snapshot=()=>new URLSearchParams(new FormData(original)).toString();
const switchDialog=async(from,to)=>{await new Promise(resolve=>{if(!from.open)return resolve();from.addEventListener('close',resolve,{once:true});from.close()});if(to.showModal)to.showModal();else to.scrollIntoView({block:"start"})};
const back=document.createElement('button');back.type='button';back.className='ssh-method-back';back.textContent='← Выбор способа';form.prepend(back);back.addEventListener('click',()=>{if(!busy){form.elements.password.value='';form.elements.middle_password.value='';window.wppCascadeMethods?.open(dialog,current?.id)}});
new MutationObserver(()=>{if(base.open)queueMicrotask(()=>{baseline=snapshot()})}).observe(base,{attributes:true,attributeFilter:['open']});
async function show(from=base){if(busy)return;current=records.get(original.elements.id.value);if(!current)return;if(!data.standalone&&snapshot()!==baseline){window.showPanelToast?.('Сначала сохраните основные настройки подключения.','error');return}form.reset();
const isHysteria=current.protocol==='hysteria';
form.querySelector('[data-ssh-transport]').textContent=isHysteria
  ?'RU-сервер пересылает Hysteria2 по UDP. TLS завершается на зарубежном VPS.'
  :'RU-сервер пересылает VLESS по TCP. TLS завершается на зарубежном VPS.';
form.querySelector('[data-ssh-firewall]').textContent=isHysteria
  ?'Откройте UDP 443 на зарубежном VPS и выбранные UDP-порты на RU. Если служба на RU уже установлена, для её обновления введите пароль root.'
  :'Откройте выбранные TCP-порты на RU.';
form.elements.host.value=current.entry.host||'';form.elements.ssh_port.value=current.ssh_port;form.elements.exit_ip.value=current.exit_ip;for(const key of ['host','ssh_port','listen_port'])form.elements['middle_'+key].value=current.middle[key];form.elements.double_hop.checked=!!current.middle.host;middlePin='';form.querySelector('[data-ssh-middle-pin]').textContent='';syncMiddle();form.elements.listen_port.value=current.entry.port||443;dialog.querySelector('[data-ssh-connection]').textContent=current.name+' · выход: '+data.domain;pin='';pinText.textContent='';status.textContent=current.entry.host?'RU-вход настроен: '+current.entry.host+':'+current.entry.port:'Укажите RU-сервер и проверьте его SSH-ключ.';install.disabled=true;form.querySelector('[data-ssh-check]').disabled=!current.entry.host;form.querySelector('[data-ssh-remove]').disabled=!current.entry.host;await switchDialog(from,dialog)};window.wppSSHCascade={open:show,busy:()=>busy};
for(const name of ['host','ssh_port'])form.elements[name].addEventListener('input',()=>{pin='';pinText.textContent='';install.disabled=true});
dialog.querySelector('[data-ssh-close]').addEventListener('click',async()=>{if(!busy){form.elements.password.value='';form.elements.middle_password.value='';await switchDialog(dialog,base)}});dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();else{form.elements.password.value='';form.elements.middle_password.value=''}});
function syncMiddle(){const enabled=form.elements.double_hop.checked;form.querySelector('[data-ssh-middle]').hidden=!enabled;for(const key of ['host','ssh_port','listen_port']){form.elements['middle_'+key].disabled=!enabled;form.elements['middle_'+key].required=enabled}form.elements.middle_password.disabled=!enabled;form.querySelector('[data-ssh-scheme]').textContent=enabled?'Клиент → RU-1 → RU-2 → зарубежный VPS → интернет':'Клиент → RU-1 → зарубежный VPS → интернет';install.disabled=!pin||(enabled&&!middlePin)}
form.elements.double_hop.addEventListener('change',syncMiddle);for(const name of ['middle_host','middle_ssh_port'])form.elements[name].addEventListener('input',()=>{middlePin='';form.querySelector('[data-ssh-middle-pin]').textContent='';syncMiddle()});
async function run(operation,second=false){if(busy||!current)return;if(operation==='provision'&&(!form.reportValidity()||!pin||(form.elements.double_hop.checked&&!middlePin)))return;if(operation==='provision'&&!confirm('Настроить RU-сервер и добавить ограниченный служебный SSH-ключ? Убедитесь, что отпечаток сервера проверен.'))return;if(operation==='remove'&&!confirm('Отключить RU-вход? После этого обновите клиентский профиль для прямого подключения к зарубежному серверу.'))return;busy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);status.style.color='';status.textContent=operation==='inspect'?'Получаем SSH-ключ сервера…':operation==='check'?'Проверяем интернет через RU и зарубежный сервер…':operation==='remove'?'Отключаем RU-вход…':'Устанавливаем службу RU и проверяем весь маршрут. Это может занять несколько минут…';try{const values={csrf:data.csrf,operation,id:current.id};if(operation==='inspect'){values.host=form.elements[second?'middle_host':'host'].value;values.ssh_port=form.elements[second?'middle_ssh_port':'ssh_port'].value}else if(operation==='provision'){for(const name of ['host','ssh_port','listen_port','exit_ip','password'])values[name]=form.elements[name].value;values.fingerprint=pin;if(form.elements.double_hop.checked){const middle={fingerprint:middlePin};for(const key of ['host','ssh_port','listen_port','password'])middle[key]=form.elements['middle_'+key].value;values.middle=JSON.stringify(middle)}}const response=await fetch(data.path+'/ssh-cascade-action',{method:'POST',headers:{Accept:'application/json'},body:new URLSearchParams(values)});if(response.redirected)throw new Error('Войдите в панель заново.');let result;try{result=await response.json()}catch(_){throw new Error('Нет ответа панели. Повторите проверку состояния.')}if(!response.ok||!result.ok)throw new Error(result.message||'Не удалось настроить RU-вход.');if(operation==='inspect'){if(second){middlePin=result.fingerprint;form.querySelector('[data-ssh-middle-pin]').textContent=middlePin}else{pin=result.fingerprint;pinText.textContent=pin}status.textContent='Сверьте SSH-отпечаток и нажмите «Настроить RU-вход».'}else if(operation==='check'){status.textContent='Выход в интернет через RU и зарубежный сервер работает.'}else{window.showPanelToast?.(operation==='remove'?'RU-вход отключён. Обновите клиентский профиль.':'RU-вход настроен. Обновите подписку или отдельное подключение.','success');location.reload()}}catch(e){status.style.color='var(--red)';status.textContent=e.message;window.showPanelToast?.(e.message,'error')}finally{if(operation==='provision'){form.elements.password.value='';form.elements.middle_password.value='';}busy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);install.disabled=!pin||(form.elements.double_hop.checked&&!middlePin);form.querySelector('[data-ssh-check]').disabled=!current.entry.host;form.querySelector('[data-ssh-remove]').disabled=!current.entry.host}}
form.querySelector('[data-ssh-middle-inspect]').addEventListener('click',()=>run('inspect',true));form.querySelector('[data-ssh-inspect]').addEventListener('click',()=>run('inspect'));form.querySelector('[data-ssh-check]').addEventListener('click',()=>run('check'));form.querySelector('[data-ssh-remove]').addEventListener('click',()=>run('remove'));form.addEventListener('submit',e=>{e.preventDefault();run('provision')});
})();</script>'''
